/bin/bash -lc "cd /work && python - <<'PY'
import sim, mujoco, numpy as np
s=sim.Sim(); hand=mujoco.mj_name2id(s.model,mujoco.mjtObj.mjOBJ_BODY,'hand')
a=s.model.jnt_range[:7,0]; b=s.model.jnt_range[:7,1]

def fk(q):
    s.data.qpos[:7]=q
    s.data.qpos[7]=0; s.data.qpos[8]=0
    mujoco.mj_forward(s.model,s.data)
    return s.data.xpos[hand].copy()

def search(tgt,seed=None,iters=20000):
    if seed is None:
        best=np.random.uniform(a,b,size=7)
    else:
        best=seed.copy()
    bestd=np.linalg.norm(fk(best)-tgt)
    for _ in range(iters):
        if np.random.rand()<0.3:
            q=np.random.uniform(a,b,size=7)
        else:
            q=np.clip(best + np.random.normal(scale=0.35,size=7),a,b)
        d=np.linalg.norm(fk(q)-tgt)
        if d<bestd:
            best,bestd=q,d
    return bestd,best,fk(best)

cup=np.array([0.48,-0.12,0.46])
bin=np.array([0.70,0.14,0.52])
bin_low=np.array([0.70,0.14,0.45])
seed=np.array([ 2.29058033,-1.57013241,-1.09153583,-1.48392606,1.41087359,0.20687644,-0.64145235])
for name,t in [('cup0.46',cup),('cup0.42',np.array([0.48,-0.12,0.43])),('bin0.52',bin),('bin0.45',bin_low),('cup_over',np.array([0.48,-0.12,0.60]))]:
    d,q,p=search(t,seed=seed)
    print(name,d,q,p)
